<?php if(in_array($kind,['assignment_plans','exam_plans'],true)): ?><form method="post" action="/study/<?= e($kind) ?>/<?= e($record['id']) ?>/generate"><?= csrf_field() ?><button class="secondary"><?= e(t('Create planned study tasks')) ?></button></form><?php endif; ?>
<?php if($kind==='cards'):$review=Db::one('SELECT * FROM study_card_reviews WHERE card_id=? ORDER BY id DESC LIMIT 1',[$record['id']]); ?><p><?= e(t('Next review:')) ?> <?= e($review['next_on']??t('Today')) ?></p><form class="inline" method="post" action="/study/cards/<?= e($record['id']) ?>/review"><?= csrf_field() ?><label><?= e(t('Recall')) ?><select name="rating"><option value="again"><?= e(t('Again')) ?></option><option value="good"><?= e(t('Good')) ?></option><option value="easy"><?= e(t('Easy')) ?></option></select></label><button class="secondary"><?= e(t('Save review')) ?></button></form><?php endif; ?>
<?php if($kind==='references'): ?><h4><?= e(t('APA book/web reference')) ?></h4><p><?= e(StudyService::citation($d,'apa')) ?></p><h4><?= e(t('Harvard book/web reference')) ?></h4><p><?= e(StudyService::citation($d,'harvard')) ?></p><p class="muted"><?= e(t('Check your institution\'s required variant. Journal, chapter and other source types need their additional metadata.')) ?></p><?php endif; ?>
<?php if($kind==='groups'):$minutes=[];foreach(StudyService::rows('contributions')as $c)if($c['fields']['project']===$record['id'])$minutes[$c['fields']['person']]=($minutes[$c['fields']['person']]??0)+$c['fields']['minutes']; ?><h4><?= e(t('Recorded member contributions')) ?></h4><?php foreach($minutes as $person=>$n): ?><p><?= e($person) ?> · <?= e($n) ?> <?= e(t('minutes')) ?></p><?php endforeach; ?><?php if($d['work_project_id']!==null): ?><a href="/work/project/<?= e($d['work_project_id']) ?>"><?= e(t('Open linked project board')) ?></a><?php endif; ?><?php endif; ?>
<?php if($kind==='papers'): ?><p><?= e(t('Score:')) ?> <?= e(round($d['score']/$d['maximum']*100,1)) ?>%</p><?php endif; ?>
<?php if($kind==='supervision'&&$d['next_action']&&$d['next_due']): ?><form method="post" action="/study/supervision/<?= e($record['id']) ?>/task"><?= csrf_field() ?><button class="secondary"><?= e(t('Create linked follow-up task')) ?></button></form><?php endif; ?>
